82	    newsUrl: "",
83	    newsDesc: "",
84	    historyList: []
85	  },
86	
87	  onInit() {
88	    this.isDark = getThemeSync()
89	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
90	    this.modeLabel = this.isDark ? "深色" : "浅色"
