103	  updateClock() {
104	    var now = new Date()
105	    this.currentTime = pad(now.getHours()) + ":" + pad(now.getMinutes())
106	  },
107	
108	  updateDate() {
109	    var now = new Date()
110	    var weekDays = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"]
111	    this.currentDate = now.getFullYear() + "年" + (now.getMonth() + 1) + "月" + now.getDate() + "日 " + weekDays[now.getDay()]
112	  },
113	
114	  toggleTheme() {
115	    this.isDark = !this.isDark
116	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
117	    this.modeLabel = this.isDark ? "深色" : "浅色"
118	    setTheme(this.isDark)
119	  },
120	
121	  goNews() {
122	    router.push({ uri: "pages/news" })
123	  },
124	
125	  goWeather() {
126	    router.push({ uri: "pages/weather" })
127	  },
128	
129	  goExpress() {
