131	  },
132	
133	  showNewsDetail() {
134	    if (!this.newsTitle || this.newsTitle === "正在加载新闻...") return
135	    router.push({
136	      uri: "pages/detail",
137	      params: {
138	        title: this.newsTitle,
139	        description: this.newsDesc,
140	        source: this.newsSource,
141	        url: this.newsUrl,
142	        isDark: this.isDark
143	      }
144	    })
145	  },
146	
147	  loadWeather() {
148	    var self = this
149	    storage.get({
150	      key: CITY_STORAGE_KEY,
151	      success: function (data) {
152	        var city = data || "北京"
153	        self.fetchWeather(city)
154	      },
155	      fail: function () {
156	        self.fetchWeather("北京")
157	      }
158	    })
159	  },
160	
161	  fetchWeather(city) {
162	    var cacheKey = "weather_" + city
163	    var cached = getCached(cacheKey)
164	    if (cached) {
165	      this.weatherSummary = cached.title + " " + cached.message + " " + cached.subtitle
166	      return
167	    }
168	    this.weatherSummary = city + " 获取天气中..."
169	    getWeather(city).then((info) => {
170	      setCache(cacheKey, info, 10 * 60 * 1000)
171	      this.weatherSummary = info.title + " " + info.message + " " + info.subtitle
172	    }).catch(() => {
173	      this.weatherSummary = city + " 天气获取失败"
174	    })
175	  },
176	
177	  loadNews() {
178	    var cacheKey = "news_politics"
179	    var cached = getCached(cacheKey)
180	    if (cached && cached.length) {
181	      var item = cached[0]
182	      this.newsTitle = item.title
183	      this.newsSource = item.source + " · " + item.published
184	      this.newsUrl = item.url
185	      this.newsDesc = item.description
186	      return
187	    }
188	    getLatestNews({ categories: ["politics"], pageSize: 50 }).then((list) => {
189	      if (list && list.length) {
190	        setCache(cacheKey, list, 5 * 60 * 1000)
191	        this.newsTitle = list[0].title
192	        this.newsSource = list[0].source + " · " + list[0].published
193	        this.newsUrl = list[0].url
194	        this.newsDesc = list[0].description
195	      }
196	    }).catch(() => {
197	      this.newsTitle = "新闻获取失败"
198	    })
199	  },
200	
201	  formatHistoryYear(year) {
202	    var y = parseInt(year, 10)
203	    if (isNaN(y)) return year + "年"
204	    if (y < 0) return "公元前" + Math.abs(y) + "年"
205	    return y + "年"
206	  },
207	
208	  loadHistory() {
209	    var cacheKey = "today_history"
210	    var cached = getCached(cacheKey)
211	    if (cached && cached.length) {
212	      this.historyList = cached
213	      return
214	    }
215	    getTodayInHistory().then((list) => {
216	      if (list && list.length) {
217	        var formatted = list.map((item) => {
218	          return { title: item.title, year: item.year, yearLabel: this.formatHistoryYear(item.year), desc: item.desc, link: item.link }
219	        })
220	        setCache(cacheKey, formatted, 30 * 60 * 1000)
221	        this.historyList = formatted
222	      }
223	    }).catch(() => {
224	      // 天气和历史加载失败时静默处理
225	    })
226	  }
227	}
