135	import { getThemeSync, setTheme } from "../../common/theme"
136	
137	function pad(value) {
138	  return value < 10 ? "0" + value : "" + value
139	}
140	
141	var SAVED_LIST_KEY = "infoExpressSaved"
142	
143	export default {
144	  private: {
145	    isDark: false,
146	    themeButtonText: "深色模式",
147	    modeLabel: "浅色",
148	    currentTime: "--:--",
149	    trackingNo: "",
150	    expressLoading: false,
151	    expressStateText: "",
152	    hasError: false,
153	    errorText: "",
154	    showKeyboard: false,
155	    savedList: [],
156	    expressInfo: {
157	      title: "请输入运单号",
158	      subtitle: "tmini-快递查询",
159	      message: "请在下方输入框输入快递运单号进行查询",
160	      status: "",
161	      details: []
162	    }
163	  },
164	
165	  onInit() {
166	    this.isDark = getThemeSync()
167	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
168	    this.modeLabel = this.isDark ? "深色" : "浅色"
169	    this.updateClock()
170	    this.loadSavedList()
171	  },
172	
173	  onShow() {
174	    this.updateClock()
175	  },
176	
177	  updateClock() {
178	    var now = new Date()
179	    this.currentTime = pad(now.getHours()) + ":" + pad(now.getMinutes())
180	  },
181	
182	  toggleTheme() {
183	    this.isDark = !this.isDark
184	    this.themeButtonText = this.isDark ? "浅色模式" : "深色模式"
185	    this.modeLabel = this.isDark ? "深色" : "浅色"
186	    setTheme(this.isDark)
187	  },
188	
189	  goHome() {
190	    router.push({ uri: "pages/index" })
191	  },
192	
193	  goNews() {
194	    router.back()
195	  },
196	
197	  goWeather() {
198	    router.push({ uri: "pages/weather" })
199	  },
200	
201	  toggleKeyboard() {
202	    this.showKeyboard = !this.showKeyboard
203	  },
204	
205	  onKeyTap(key) {
206	    if (key === "DEL") {
207	      if (this.trackingNo.length > 0) {
208	        this.trackingNo = this.trackingNo.substring(0, this.trackingNo.length - 1)
209	      }
210	    } else if (key === "CLR") {
211	      this.trackingNo = ""
212	    } else if (key === "OK") {
213	      this.showKeyboard = false
214	    } else {
215	      this.trackingNo += key
216	    }
217	  },
218	
219	  queryExpress() {
220	    var trackingNo = this.trackingNo.trim()
221	    if (!trackingNo) {
222	      this.expressInfo = {
223	        title: "请输入运单号",
224	        subtitle: "tmini-快递查询",
225	        message: "请在下方输入框输入快递运单号进行查询",
226	        status: "",
227	        details: []
228	      }
229	      return
230	    }
231	
232	    this.showKeyboard = false
233	    this.expressLoading = true
234	    this.expressStateText = "正在查询快递信息"
235	
236	    getExpress(trackingNo).then((info) => {
237	      this.expressInfo = info
238	      this.expressLoading = false
239	      this.saveToList(trackingNo)
240	    }).catch((err) => {
241	      this.expressLoading = false
242	      this.hasError = true
243	      this.errorText = "快递查询失败: " + err.message
244	    })
245	  },
246	
247	  loadSavedList() {
248	    var self = this
249	    storage.get({
250	      key: SAVED_LIST_KEY,
251	      success: function (data) {
252	        try {
253	          self.savedList = JSON.parse(data) || []
254	        } catch (e) {
255	          self.savedList = []
256	        }
257	      },
258	      fail: function () {
259	        self.savedList = []
260	      }
261	    })
262	  },
263	
264	  saveToList(trackingNo) {
265	    if (!trackingNo) return
266	    var list = this.savedList.filter(function (item) { return item !== trackingNo })
267	    list.unshift(trackingNo)
268	    if (list.length > 10) list = list.slice(0, 10)
269	    this.savedList = list
270	    storage.set({
271	      key: SAVED_LIST_KEY,
272	      value: JSON.stringify(list)
273	    })
274	  },
275	
276	  removeSaved(index) {
277	    var list = this.savedList.filter(function (_, i) { return i !== index })
278	    this.savedList = list
279	    storage.set({
280	      key: SAVED_LIST_KEY,
281	      value: JSON.stringify(list)
282	    })
283	  },
284	
285	  loadSaved(item) {
286	    this.trackingNo = item
287	    this.queryExpress()
288	  }
289	}
290	</script>
