  if (cachedTheme !== null) {
    callback(cachedTheme)
    return
  }
  storage.get({
    key: THEME_KEY,
    success: function (data) {
      cachedTheme = data === "true"
      callback(cachedTheme)
    },
    fail: function () {
      cachedTheme = false
      callback(false)
    }
  })
}

export function setTheme(isDark) {
  cachedTheme = isDark
  storage.set({
    key: THEME_KEY,
    value: isDark ? "true" : "false"
  })
}

