// 2. Extract nested content: find opening tag, then count div depth to find matching close
var lowerHtml = content.toLowerCase()
function extractNested(html, openPattern) {
  let openMatch = openPattern.exec(html)
  if (!openMatch) {
    return null
  }
  let openEnd = openMatch.index + openMatch[0].length
  let depth = 1
  let pos = openEnd
  while (depth > 0 && pos < html.length) {
    let nextOpen = lowerHtml.indexOf("<div", pos)
    let nextClose = lowerHtml.indexOf("</div>", pos)

    // 找较近的一个，无需构造数组和排序
    if (nextOpen === -1 && nextClose === -1) break
    if (nextOpen === -1) nextOpen = html.length
    if (nextClose === -1) nextClose = html.length

    if (nextOpen < nextClose) {
      depth++
      pos = openEnd + 4
    } else {
      depth--
      if (depth === 0) {
        return html.substring(openEnd, nextClose)
      }
      pos = nextClose + 6
    }
  }
  return html.substring(openEnd)
}

