126	    const descMatch = html.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']*)["'][^>]*>/i);
127	    if (descMatch && descMatch[1]) {
128	      description = descMatch[1].trim();
129	    }
130	    
131	    // 移除脚本和样式标签
132	    const cleanHtml = html.replace(/<script[^>]*>.*?<\/script>/gis, '').replace(/<style[^>]*>.*?<\/style>/gis, '');
133	    
134	    // 尝试提取主要内容区域
