141	      /<div[^>]*class=["'][^"']*(?:content|article|post|entry)[^"']*["'][^>]*>(.*?)<\/div>/gis,
142	      /<div[^>]*id=["'][^"']*(?:content|article|post|entry|main)[^"']*["'][^>]*>(.*?)<\/div>/gis
143	    ];
144	    
145	    // 尝试提取内容区域
146	    for (const selector of contentSelectors) {
